async function api(route,method='GET',data){const r=await fetch(`/api${route}`,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},...(data?{body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw new Error(result.error||'Servidor indisponível.');return result;}
