function hero(p,seat,enemy=false){const h=heroes(p),ownGearTarget=!enemy&&selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'&&(p.heroGear||[]).length<1,target=enemy&&selected&&(selected.kind==='skill'||selected.kind==='ultimate'||(selected.kind==='attack'&&room.players[seat].lanes[selected.lane].length===0)||(selected.kind==='campaign'&&selected.tactic==='breach'))||ownGearTarget,targetLabel=ownGearTarget?'EQUIPAR':target&&selected?.kind==='attack'?'ATACAR LÍDER':target&&selected?.kind==='ultimate'?'SUPREMA':target&&selected?.kind==='campaign'?'ROMPER':target?'ALVO':'';return `<div class="hero ${enemy?'enemy-hero':'player-hero'} ${p.faction}" data-hero="${seat}"><div class="hero-meta"><small>${p.boss?'CHEFE DE DUNGEON':enemy?p.rival?.style||'RIVAL':'SEU LÍDER'} ${p.passed?'· ENCERROU':''}</small><strong>${!enemy?esc(profile.name):h.name}</strong><span>${h.title}</span></div><button class="hero-portrait ${target?'valid-target':''} ${ownGearTarget?'gear-target':''}" data-target="hero" data-seat="${seat}" ${!target?'tabindex="-1"':''} aria-label="${ownGearTarget?'Equipar item em ':target?'Atacar ':'Líder '}${h.name}, ${p.health} de vida">${art(p.rival?.avatar||(!enemy&&profile.character?.avatar)||(p.boss?'boss':p.faction))}<b class="hero-health">${Math.max(0,p.health)}</b><span class="hero-ring"></span>${targetLabel?`<span class="target-cue ${ownGearTarget?'equip-cue':''}">${targetLabel}</span>`:''}${p.heroGear?.length?`<span class="hero-gear-display">${gearBadges(p.heroGear)}</span>`:''}</button><span class="hero-life-track" aria-label="${p.health} de ${p.maxHealth||24} vida"><i style="--hp:${Math.max(0,Math.min(100,(p.health/(p.maxHealth||24))*100))}%"></i></span><div class="hero-renown"><b>✦ ${p.renown}<small>/12</small></b><span>RENOME</span><button class="battle-level-badge" data-rpg-open data-rpg-seat="${seat}" title="Progressão desta partida">NV ${p.battleLevel||1} · ${p.battleXP||0} XP</button></div></div>`;}
function tokenUnit(u,lane,seat){const mine=seat===room.seat,c=CARDS[u.cardId];let target=false;
  if(selected&&canAct()){if(selected.kind==='attack')target=!mine&&lane===selected.lane;else if(['skill','ultimate'].includes(selected.kind))target=!mine;else if(selected.kind==='campaign'){if(['immunity','field_repair','logistics'].includes(selected.tactic))target=mine&&(selected.tactic!=='field_repair'||u.health<u.maxHealth)&&(selected.tactic!=='immunity'||(!u.guard&&c.keyword!=='guard'&&u.guardUntilRound!==room.round));else if(selected.tactic==='breach')target=!mine;}else if(selected.kind==='card'){const card=CARDS[selected.cardId];target=mine?(card.type==='equipment'&&u.equipment<2||['pounce','rally','guard'].includes(card.effect)):['damage','execute','rend','drain'].includes(card.effect);}}
  const targetVerb=selected?.kind==='attack'?'ATACAR':selected?.kind==='ultimate'?'EXECUTAR':selected?.kind==='skill'?'HABILIDADE':selected?.kind==='campaign'?(selected.tactic==='immunity'?'PROTEGER':selected.tactic==='field_repair'?'REPARAR':selected.tactic==='logistics'?'MOVER':selected.tactic==='breach'?'ROMPER':'ALVO'):selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'?'EQUIPAR':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='pounce'?'SALTO':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='rally'?'REFORÇAR':selected?.kind==='card'&&CARDS[selected.cardId]?.effect==='guard'?'PROTEGER':'ALVO';
  return `<button class="fighter ${c.faction} ${mine?'allied':'hostile'} ${u.ready!==false?'ready':'exhausted'} ${target?'valid-target':''} ${selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'&&target?'equipment-target':''} ${selected?.uid===u.uid?'chosen-fighter':''}" data-unit="${u.uid}" data-seat="${seat}" data-lane-id="${lane}" data-preview="${u.cardId}" aria-label="${c.name}, ataque ${combatAttack(u)}, vida ${u.health}, nível ${u.level||1}${mine&&u.ready!==false?', pronto para atacar':''}">${art(u.cardId)}<span class="fighter-bevel"></span><span class="fighter-name">${c.name}</span><b class="fighter-attack">${combatAttack(u)}</b><b class="fighter-health">${u.health}</b><span class="fighter-level">${(u.level||1)>1?'★':''} ${u.level||1}</span>${target?`<span class="target-cue ${selected?.kind==='card'&&CARDS[selected.cardId]?.type==='equipment'?'equip-cue':''}">${targetVerb}</span>`:''}${u.bleed?'<span class="bleed" title="Sangrando">♦</span>':''}${u.equipment?`<span class="equipment-pips">${'◆'.repeat(u.equipment)}</span>`:''}${u.gearItems?.length?`<span class="gear-status" aria-label="${u.gearItems.length} equipamentos">${gearBadges(u.gearItems)}</span>`:''}${mine?`<span class="ready-label">${u.ready!==false?'⚔':'✓'}</span>`:''}</button>`;
}
function laneTactics(laneId,me,ready){
 const used=me.ordersUsed?.[laneId]||Object.keys(ORDERS).some(id=>ORDERS[id].category===laneId&&me.ordersUsed?.[id]),enemy=room.players[1-room.seat];
 return `<div class="lane-tactics" data-lane="${laneId}">${Object.entries(ORDERS).filter(([,o])=>o.category===laneId).map(([id,o])=>{
 const impossible=id==='tribute'&&(enemy.tributeActive||enemy.passed)||id==='rations'&&(me.hand.length>=10||!me.deckCount);
 return `<button class="tactic-btn ${selected?.tactic===id?'active':''}" data-campaign="${laneId}:${id}" ${!ready||used||impossible||(me[o.resource]||0)<o.cost?'disabled':''} title="${o.text} Uma ordem desta frente por rodada."><span>${{tribute:'TRIBUTO',bribe:'PACTO',immunity:'GUARDA',logistics:'MOVER',field_repair:'SOCORRO',rations:'COMPRAR',breach:'RUPTURA',plunder:'INCURSÃO'}[id]}</span><small>${used?'✓ USADA':o.cost+' '+(laneId==='court'?'♜':laneId==='crypt'?'◇':'⚔')}</small></button>`;
 }).join('')}</div>`;
}
function battle(){const me=room.players[room.seat],enemy=room.players[1-room.seat],h=HEROES[me.faction],ready=canAct(),event=EVENTS[room.round-1];
  const instruction=busy?'O SANGUE ESTÁ SENDO DERRAMADO…':room.phase==='finished'?'A CAÇADA TERMINOU':!ready?'AGUARDE SEU RIVAL':selected?.kind==='campaign'?(selected.tactic==='bribe'?'ESCOLHA UMA FRENTE PARA SUBORNAR (+2 PODER)':selected.tactic==='immunity'?'ESCOLHA UM ALIADO PARA CONCEDER SALVA-GUARDA':selected.tactic==='breach'?'ESCOLHA UM COMBATENTE INIMIGO PARA A RUPTURA (2 DANO)':selected.tactic==='field_repair'?'ESCOLHA UM ALIADO PARA REPARAR (+3 VIDA)':selected.tactic==='logistics'?'CLIQUE NO ALIADO QUE DESEJA DESLOCAR':selected.tactic==='logistics_dest'?'CLIQUE NA FRENTE DE DESTINO DO ALIADO':'ORDEM DE CAMPANHA'):!selected?'JOGUE UMA CARTA OU CLIQUE EM UM ALIADO PARA ATACAR':selected.kind==='attack'?'ESCOLHA UMA PRESA NA MESMA FRENTE':selected.kind==='skill'||selected.kind==='ultimate'?'ESCOLHA UM INIMIGO OU O LÍDER RIVAL':CARDS[selected.cardId].type==='equipment'?'EQUIPE UM ALIADO OU SEU LÍDER':['pounce','rally','guard'].includes(CARDS[selected.cardId].effect)?'ESCOLHA O ALIADO QUE RECEBERÁ O EFEITO':['damage','execute','rend','drain'].includes(CARDS[selected.cardId].effect)?'ESCOLHA UM COMBATENTE INIMIGO':'ESCOLHA UMA FRENTE PARA INVOCAR';
  const turnMode=room.phase==='finished'?'finished':ready?'active':me.passed?'locked':'enemy',turnTitle=turnMode==='active'?(enemy.passed?'ÚLTIMA AÇÃO':'SUA VEZ'):turnMode==='enemy'?'TURNO DO RIVAL':turnMode==='locked'?'VOCÊ ENCERROU':'CAÇADA ENCERRADA';
  return `<main class="arena ${me.faction}" aria-label="Arena de combate"><div class="scene-bg"></div><div class="arena-vignette"></div><div class="fog fog-one"></div><div class="embers" aria-hidden="true">${'<i></i>'.repeat(12)}</div><header class="battle-top"><div class="battle-brand">BLOOD<span>MOON</span><small>${room.mode==='dungeon'?'O SEPULCRO DO REI':'FORTALEZA DA ÚLTIMA NOITE'}</small></div>${controls()}</header><div class="round-medallion"><b>${room.round}</b><span>RODADA</span><small>DE 8</small></div><div class="event-pill"><span>☾</span><div><strong>${event.name}</strong><small>${event.lane?`+1 Renome · ${LANES.find(l=>l.id===event.lane).name}`:'A noite pertence aos que sobrevivem'}</small></div></div>${hero(enemy,1-room.seat,true)}<div class="enemy-hand" aria-label="${enemy.handCount} cartas na mão rival">${Array.from({length:Math.min(enemy.handCount,10)},(_,i)=>`<i style="--back-angle:${(i-(enemy.handCount-1)/2)*5}deg">◈</i>`).join('')}</div><div class="battlefield"><div class="battlefield-surface"></div>${LANES.map((l,li)=>`<section class="battle-lane lane-${l.id}" data-zone="${l.id}" aria-label="Frente ${l.name}"><div class="squad enemy-squad count-${enemy.lanes[l.id].length}" data-count="${enemy.lanes[l.id].length}">${enemy.lanes[l.id].map(u=>tokenUnit(u,l.id,1-room.seat)).join('')||'<span class="vacant enemy-vacant">◇</span>'}</div><div class="lane-divider"><b class="power enemy-power">${power(enemy,l.id)}</b><button class="lane-title" data-modal="battle-guide" title="${l.reward} · toque para regras"><i>${l.icon}</i>${l.name}<small>${l.id==='court'?'INFLUÊNCIA':l.id==='crypt'?'SAQUE':'DANO DIRETO'}</small><em class="lane-campaign-tag">${l.id==='court'?`🏛️ ${me.favors||0}`:l.id==='crypt'?`📦 ${me.supplies||0}`:`⚔️ ${me.siege||0}`}</em></button><b class="power own-power">${power(me,l.id)}</b>${laneTactics(l.id,me,ready)}</div><div class="squad player-squad count-${me.lanes[l.id].length}" data-count="${me.lanes[l.id].length}">${me.lanes[l.id].map(u=>tokenUnit(u,l.id,room.seat)).join('')||`<button class="vacant" data-deploy="${l.id}" aria-label="Invocar em ${l.name}"><span>＋</span></button>`}</div><button class="drop-zone ${selected?.kind==='card'?'show-drop':''}" data-deploy="${l.id}" aria-label="Jogar carta em ${l.name}" ${!ready||selected?.kind!=='card'?'disabled':''}>${l.icon}<span>INVOCAR</span></button></section>`).join('')}</div><aside class="battle-left"><div class="deck-stack"><i></i><i></i><div>◈<b>${me.deckCount}</b></div><small>BARALHO</small></div><button data-modal="chronicle" class="history-button" title="Histórico">≋</button><div class="kill-count">☠ ${me.kills||0}<small>ABATES</small></div></aside><aside class="battle-right"><div class="frenzy-meter ${me.rage>=6?'charged':''}"><span>FRENESI</span><b>${me.rage}<small>/6</small></b><div>${Array.from({length:6},(_,i)=>`<i class="${i<me.rage?'filled':''}"></i>`).join('')}</div></div><button data-power="ultimate" class="ultimate-button ${selected?.kind==='ultimate'?'active':''}" ${!ready||me.rage<6||me.ultimateUsed?'disabled':''} title="5 de dano. +1 ataque aos aliados da frente até o fim da rodada. Vampiros também curam 3."><span>✹</span><small>${h.ultimate}</small></button><button data-pass class="end-turn" ${!ready?'disabled':''}><span>⚔</span><b>${me.passed?'AGUARDANDO':'ENCERRAR'}</b><small>RODADA</small></button><div class="combo-count"><span>COMBO</span>${[0,1,2].map(i=>`<i class="${i<me.combo?'lit':''}">◆</i>`).join('')}</div></aside><div class="battle-instruction turn-${turnMode}" role="status" aria-live="polite"><span class="turn-glyph">${turnMode==='active'?'⚔':turnMode==='enemy'?'☾':turnMode==='locked'?'✓':'◇'}</span><span class="turn-copy"><b>${turnTitle}</b><small>${instruction}</small></span>${selected?'<button data-cancel aria-label="Cancelar seleção">✕</button>':''}</div>${hero(me,room.seat)}<div class="player-abilities"><button class="skill-button ${selected?.kind==='skill'?'active':''}" data-power="skill" ${!ready||me.energy<2||me.skillUsed?'disabled':''} title="${h.description}"><span>${me.faction==='vampire'?'♦':'≋'}</span><b>2</b></button><small>${h.skill}</small></div><div class="energy-hud"><div class="energy-orb">${me.energy}</div>${me.tributeActive?'<span class="tax-alert">♜ PRÓXIMA CARTA +1</span>':''}<div><span>${FACTIONS[me.faction].resource.toUpperCase()}</span><div class="energy-pips">${Array.from({length:Math.min(7,room.round+2)},(_,i)=>`<i class="${i<me.energy?'filled':''}"></i>`).join('')}</div></div></div><div class="hand-dock"><div class="hand-fan count-${me.hand.length}">${me.hand.map((c,i)=>card(c.cardId,c.uid,i,me.hand.length)).join('')}</div></div><div class="battle-footer"><span>${room.mode==='duel'?'ARENA ONLINE · PACTO DE VÉSPERA':room.mode==='dungeon'?'DUNGEON · MALDIÇÃO: −1 VIDA / RODADA':'CAÇADA · RIVAL AUTOMÁTICO'}</span><small>ARRASTE PARA INVOCAR · CLIQUE PARA ATACAR · ESC CANCELA</small><span>${me.hand.length}/10 CARTAS</span></div>${room.phase==='finished'?resultHTML():''}<div id="effects" aria-hidden="true"></div></main>`;
}
function resultHTML(){return battleResult(room,card);}
function deckModalBody(){
  if(!profile?.decks)return '<p>Seu arsenal ainda está sendo preparado.</p>';
  if(!editingDeckId){
    const decks=profile.decks.map(d=>{const skin=deckBoxSkin(d),box=DECK_BOX_SKINS[skin],choices=Object.entries(DECK_BOX_SKINS).filter(([,choice])=>choice.faction===d.faction),ready=loadoutStatus(profile,d).ready;
      return `<article class="deck-row ${profile.activeDecks?.[d.faction]===d.id?'active':''}"><button class="deck-box-display ${d.faction}" data-deck-box-customize="${d.id}" aria-label="Personalizar ${esc(d.name)} · ${box.name}"><img src="/assets/deckboxes/${skin}.svg" alt="Ilustração da deck box ${box.name}"><span class="deck-box-seal">${d.faction==='vampire'?'☾':'ᛟ'}</span><b>${d.cards.length}<small>/20</small></b></button><div class="deck-overview"><small class="deck-box-kicker">CAIXA · ${d.faction==='vampire'?'CORTE RUBRA':'ALCATEIA'}</small><strong>${esc(d.name)}</strong><span class="deck-archetype">${esc(analyzeDeck(d.cards).style)} · ${d.cards.length}/20 CARTAS</span><p class="deck-validation ${ready?'valid':''}">${esc(loadoutStatus(profile,d).error||'✓ Lista pronta · relíquias conferidas')}</p><small class="deck-box-description">${box.detail}</small>${d.autoRefills?.length?`<em class="deck-auto-refill">↻ ${d.autoRefills.length} RESERVA(S) · REPARO NO RELICÁRIO</em>`:''}${deckBoxPicker===d.id?`<div class="deck-box-skins" aria-label="Escolher ilustração da deck box">${choices.map(([id,choice])=>`<button data-deck-box-skin="${id}" data-deck-id="${d.id}" aria-pressed="${skin===id}"><img src="/assets/deckboxes/${id}.svg" alt=""><span><b>${choice.name}</b><small>${choice.detail}</small></span></button>`).join('')}</div>`:''}</div><div class="deck-actions"><button data-deck-box-customize="${d.id}">${deckBoxPicker===d.id?'FECHAR PERSONALIZAÇÃO':'✧ PERSONALIZAR CAIXA'}</button><button data-loadout-deck="${d.id}">⚒ EQUIPAMENTOS</button><button data-deck-edit="${d.id}">EDITAR DECK</button>${profile.activeDecks?.[d.faction]===d.id?'<span class="deck-active">EM USO</span>':`<button data-deck-activate="${d.id}">EQUIPAR</button>`}</div></article>`;
    }).join('');
    return `<button class="menu-option" data-modal="loadout">⚒ PREPARAR EQUIPAMENTOS · TROCA RÁPIDA</button><p>Decks de 20 cartas · mínimo ${DECK_RULES.minUnits} aliados e ${DECK_RULES.minAffordableUnits} aliados de custo 2 ou menos · até ${DECK_RULES.maxCopies} cópias (1 lendária). As cartas dos seus decks continuam disponíveis para outras listas.</p><div class="deck-list">${decks}</div><div class="new-deck-row"><span>NOVA LISTA · escolha a facção e monte usando sua coleção.</span>${Object.keys(FACTIONS).map(id=>`<button data-deck-new="${id}">${id==='vampire'?'CORTE RUBRA':'ALCATEIA'}</button>`).join('')}</div>`;
  }  const saved=profile.decks.find(d=>d.id===editingDeckId),f= saved?.faction||editingDeckFaction,draft=deckDraft||[],owned=deckCollection(profile.collection||{},saved?.autoRefills||[]),items=profile.items||[],counts=countCards(draft),stats=analyzeDeck(draft);let error='';try{validateDeck(draft,f,owned,items);}catch(e){error=e.message;}const refillNotice=saved?.autoRefills?.length?` · RESERVA AUTOMÁTICA: ${saved.autoRefills.map(refill=>`${CARDS[refill.replacementId]?.name||refill.replacementId} no lugar de ${CARDS[refill.equipmentId]?.name||refill.equipmentId}`).join(' / ')} · repare a peça no Relicário para recuperá-la`:'';
  const pool=Object.values(CARDS).filter(c=>(c.faction===f||c.faction==='neutral')&&matchesSearch(c)).sort((a,b)=>a.cost-b.cost||a.name.localeCompare(b.name));
  return `<div class="deck-editor-head"><button data-deck-back>← TODAS AS LISTAS</button><label>Nome da lista<input id="deck-name" maxlength="28" value="${esc(deckDraftName||saved?.name||'Meu deck')}"></label><div class="deck-ratio ${stats.balance>112?'high':stats.balance<78?'low':''}"><b>${stats.balance}</b><small>ORÇAMENTO MÉDIO</small></div></div><div class="deck-stats"><span>${draft.length}/20 CARTAS</span><span>${stats.units} ALIADOS</span><span>${stats.equipment}/${DECK_RULES.maxEquipment} ITENS</span><span>MÉDIA ${stats.averageCost} RECURSOS</span><span>${stats.synergyCards} SINERGIAS</span><strong>${stats.style}</strong></div><p class="deck-validation ${error?'':'valid'}">${error||'Lista legal · pronta para a caçada.'}${refillNotice}</p>${searchTools()}<div class="deck-editor-columns"><section class="deck-current"><h3>NA LISTA <small>${draft.length}/20</small></h3>${Object.entries(counts).length?Object.entries(counts).sort((a,b)=>CARDS[a[0]].cost-CARDS[b[0]].cost).map(([id,n])=>`<div class="deck-card-row"><button class="deck-inspect" data-inspect="${id}" data-preview="${id}">${art(id,"mini-art")}<span>${CARDS[id].name}<small>${CARDS[id].cost} recursos · ${CARDS[id].rarity} · régua ${cardBalance(CARDS[id])}</small></span></button><b>×${n}</b><button data-card-remove="${id}" aria-label="Remover ${CARDS[id].name}">−</button></div>`).join(''):'<p class="empty-deck">Adicione cartas da coleção.</p>'}</section><section class="deck-pool"><h3>COLEÇÃO <small>FACÇÃO + RELÍQUIAS</small></h3>${pool.map(c=>{const n=counts[c.id]||0,ownedCount=ownedCardCount(c.id,owned,items),can=ownedCount>n&&n<cardLimit(c)&&draft.length<20;return `<article class="deck-pool-tile ${ownedCount?'owned':'unowned'}">${card(c.id)}<div><span>${n}/${ownedCount} <small>NO DECK / POSSUI</small></span><button data-card-add="${c.id}" ${!can?'disabled':''} aria-label="Adicionar ${c.name}">＋</button></div></article>`;}).join('')}</section></div><div class="deck-editor-actions"><button class="gold-button" data-deck-save ${error?'disabled':''}>SALVAR LISTA</button>${saved?`<button class="menu-option" data-deck-activate="${saved.id}">EQUIPAR PARA ${f==='vampire'?'A CORTE':'A ALCATEIA'}</button>`:''}</div>`;
}
function boosterPullHTML(p,i){const c=CARDS[p.id],revealed=revealedSlots.has(i);return `<article class="booster-pull ${p.rarity} ${revealed?'is-revealed':''}" data-booster-slot="${i}" style="--reveal-delay:${i*90}ms">${revealed?card(c.id):`<button class="sealed-card" data-reveal-slot="${i}" aria-label="Revelar carta ${i+1}"><i>☾</i><b>BLOODMOON</b><small>TOQUE PARA REVELAR</small></button>`}<small>${revealed?rarityNames[p.rarity]+' · '+(p.duplicate?'DUPLICATA':'ADICIONADA'):'DESTINO SELADO'}</small>${revealed&&p.duplicate?`<b>+${ECONOMY.duplicateDust[p.rarity]} FRAGMENTOS</b>`:''}${revealed&&p.item?'<b>RELÍQUIA · DURABILIDADE 3</b>':''}</article>`;}
function boosterResultsHTML(){if(!packReveal.length||packState!=='revealed')return '';const allRevealed=revealedSlots.size===packReveal.length;return `<div class="reveal-toolbar"><h3>RECOMPENSAS DA NOITE</h3><button data-reveal-all ${allRevealed?'disabled':''}>${allRevealed?'TODAS REVELADAS':'REVELAR TODAS'}</button></div><div class="pack-reveal">${packReveal.map(boosterPullHTML).join('')}</div>`;}
function syncBoosterDOM(updateResults=false){const stage=document.querySelector('.booster-stage'),button=document.querySelector('[data-buy-booster]');if(stage){stage.classList.remove('pack-sealed','pack-opening','pack-revealed');stage.classList.add(`pack-${packState}`);}if(button){button.disabled=busy||profile.coins<ECONOMY.boosterCost;button.querySelector('small').textContent=`◈ ${ECONOMY.boosterCost} MARCAS · SALDO ${profile.coins}`;button.querySelector('span').textContent=packState==='opening'?'ROMPENDO O SELO…':packReveal.length?'ABRIR OUTRO BOOSTER':'ABRIR BOOSTER';}const balance=app.querySelector('.lobby-bottom nav [data-modal="boosters"] small');if(balance)balance.textContent=`${profile.coins} MARCAS`;const player=app.querySelector('.player-badge small');if(player)player.textContent=`${profile.xp||0} XP · ${profile.wins||0} vitórias · ${profile.coins} MARCAS`;if(updateResults){const slot=document.querySelector('.booster-results-slot');if(slot){slot.innerHTML=boosterResultsHTML();bindHover(slot);}}}
async function buyBooster(){if(busy)return;busy=true;syncBoosterDOM();try{const result=await api('/boosters/open','POST',{});profile=result.profile;packReveal=result.pulls;revealedSlots.clear();packState='opening';syncBoosterDOM(true);playSound('loot');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(resolve=>setTimeout(resolve,1100));packState='revealed';syncBoosterDOM(true);}catch(error){toast(error.message);}finally{busy=false;syncBoosterDOM();}}
function modalHTML(){if(!modal)return '';let body='',title='';
  if(modal==='character'){title='Personagem';body=characterUI(profile);}
  if(modal==='academy'){title='A jornada de Iria';body=`<div class="academy-hub"><img src="/assets/avatars/oracle.png" alt="Iria"><h3>Aprenda fazendo</h3><p>Nove exercícios na mesa real, com recursos de treino. Sem desgaste, moedas ou recompensas. Você pode sair e repetir quando quiser.</p><button class="hunt-button" data-academy-start><span>PRIMEIRO COMBATE GUIADO</span></button><h4>Depois da batalha</h4>${[['decks','1 · Construir seu estilo','20 cartas; mínimo 8 aliados, 2 baratos e até 6 equipamentos.'],['loadout','2 · Preparar relíquias','Escolha uma posição do deck e uma peça utilizável. Reservas substituem peças indisponíveis.'],['market','3 · Sustentar a aventura','Repare peças danificadas, transforme sucata e examine custos antes de criar ou negociar.'],['boosters','4 · Ampliar a coleção','Abra cartas e inspecione seus efeitos. Você não precisa comprar boosters para voltar a jogar.'],['contracts','5 · Colher recompensas','Acompanhe objetivos e receba recompensas disponíveis.'],['battle-guide','6 · Dominar as regras','Conquista, influência, evolução, tributo e economia de cada frente.']].map(([id,name,text])=>`<button class="academy-destination" data-modal="${id}"><b>${name}</b><small>${text}</small></button>`).join('')}<button class="academy-destination" data-open-realms><b>7 · Explorar os Reinos</b><small>Siga rotas conectadas, colete, reabasteça e avance na Crônica. Talentos ajudam a exploração sem aumentar poder na arena.</small></button></div>`;}
  if(modal==='loadout'){title='Armar a expedição';body=loadoutUI(profile,loadoutDeckId,loadoutSlot,card,readiness);}
  if(modal==='battle-guide'){title='Conselho de guerra';body=battleGuide(room?.players[room.seat]);}
  if(modal==='onboarding'){title='Sua primeira aventura';body=`Crie seu personagem pelo prólogo para receber seu primeiro deck e começar a campanha de Véspera.`;}
  if(modal==='guide'){title='A caçada em quatro movimentos';body=`<div class="guide-grid"><article><b>01</b><h3>Invoque</h3><p>Arraste uma carta para uma frente, ou clique na carta e depois no local. O custo sai do seu Sangue ou Fúria.</p></article><article><b>02</b><h3>Ataque</h3><p>Clique em um aliado pronto e depois no inimigo da mesma frente. Sem inimigos, ataque o líder. Ataques são gratuitos, uma vez por aliado por rodada, com revide simultâneo.</p></article><article><b>03</b><h3>Desperte</h3><p>Atacar e abater carrega Frenesi. Com 6, libere a suprema: 5 de dano e +1 ataque aos aliados da frente. O botão ao lado do seu líder usa a habilidade de 2 recursos, uma vez por rodada.</p></article><article><b>04</b><h3>Sobreviva</h3><p>Ao encerrar, aliados que ainda não atacaram trocam golpes automaticamente. Corte concede 2 Renome e cura 1; Catacumbas concede 1 Renome e loot; Caçada concede 1 Renome e causa 3 de dano. Empates não premiam. Depois, os recursos se renovam e cada jogador compra uma carta.</p></article></div><div class="guide-notes"><p><b>RPG:</b> aliados sobreviventes ganham 2 XP por abate direto e 1 XP por conquista de frente. Com 2 / 6 XP chegam aos níveis 2 / 3, ganhando +1 ataque e +2 vida por evolução. Cada aliado carrega até 2 equipamentos.</p><p><b>Combo:</b> jogue 3 cartas na mesma rodada para causar 2 de dano ao líder rival e ganhar 2 Frenesi.</p><p><b>Vitória:</b> derrube o líder ou alcance 12 Renome no confronto. Após a rodada 8, maior Renome vence; vida desempata. Morte simultânea é empate. Sangramento aplica dano no confronto e desaparece. Drenar cura pelo dano causado ao atacar, inclusive contra criaturas. Sem cartas no baralho, compras causam fadiga crescente.</p><p><b>Dungeon:</b> Mordrath tem 36 de vida e começa com uma sentinela. Sua maldição causa 1 de dano a cada nova rodada. Ao iniciar uma rodada com 18 de vida ou menos, fortalece seus aliados uma vez. Vença para obter um troféu permanente, sem bônus de poder.</p></div>`;}
  if(modal==='guide')body+=battleGuide(room?.players[room.seat]);
  if(modal==='guide')body+=`<div class="guide-notes"><p><b>Turno:</b> ações alternam entre líderes até ambos encerrarem. Recursos começam em 3, sobem +1 por rodada e param em 7. Um aliado ataca sem custo uma vez por rodada; se ainda houver inimigo na frente, o ataque direto não alcança o líder. Habilidades custam 2 e a Suprema consome 6 Frenesi.</p><p><b>Dano e estados:</b> ataques contra criaturas trocam dano simultâneo; vida chega a zero e o abate é removido antes da conquista. Sangramento acumula e causa seu valor no confronto; Drenar cura pelo dano efetivamente causado. Equipamentos dão os atributos impressos por esta partida: até 2 por criatura e 1 no líder. Salto concede +2 ataque e permite um novo ataque. Suprema e sinergias dão bônus até o fim da rodada.</p><p><b>Relicário e risco:</b> equipamento tem 3 usos. No fim de uma caçada, peças equipadas perdem 1 de durabilidade; peças de criaturas abatidas perdem 2. No relicário, repare por Marcas, crie com Marcas + Sucata ou negocie peças sem vínculo no Mercado. O Pacto não transfere itens entre jogadores. O Juramento de Sangue exige que os dois aceitem e permite saquear uma peça não vinculada; a derrota também pode custar o equipamento usado pelo líder.</p><p><b>Sinergia:</b> Escrivã e Viúva respondem a mortes aliadas; Sanguinista e Marechal respondem a rituais; Corredor e Alfa respondem a novas invocações; Uivadora responde a sangramento. Cada sinergia aciona no máximo uma vez por rodada e exige a mesma frente.</p><p><b>Construção:</b> decks têm 20 cartas, ao menos 8 aliados e 2 aliados de custo 2 ou menos para mãos iniciais jogáveis; média até 4,5 recursos, até 6 equipamentos e cópias limitadas a 2 (1 lendária). Só entram cartas da facção e relíquias neutras. A régua no editor estima orçamento; orienta a curva sem alterar o combate. O saque de Catacumbas é uma cópia de item temporária da partida; vitórias na dungeon dão uma peça permanente.</p></div>`;
  if(modal==='collection'){title=`${CARD_SET.name} · coleção`;body=`<div class="collection-wallet"><b>${Object.values(profile?.collection||{}).reduce((a,n)=>a+n,0)+Object.values(profile?.items||[]).length} cartas e itens próprios</b><span>${profile?.dust||0} Fragmentos · ${profile?.scrap||0} Sucata</span><button data-modal="boosters">ABRIR BOOSTERS</button><button data-modal="decks">MONTAR DECK</button><button data-modal="market">RELICÁRIO & MERCADO</button></div>${searchTools()}<div class="collection-filters">${[['all','TODAS'],['vampire','VAMPIROS'],['werewolf','LOBISOMENS'],['neutral','RELÍQUIAS']].map(([id,name])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${name}</button>`).join('')}</div><div class="collection-grid">${collectionCardGridHTML()}</div>`;}
  if(modal==='craft-result'&&craftedReveal){const c=CARDS[craftedReveal.id],gear=c.type==='equipment',item=craftedReveal.items?.[0];title=gear?'Relíquia forjada':'Carta criada';body=`<section class="craft-result-scene ${c.faction} rarity-${c.rarity}"><div class="craft-result-glow"></div><div class="craft-result-card">${card(c.id)}</div><div class="craft-result-copy"><small>${gear?'NOVA PEÇA · RELICÁRIO':'NOVA AQUISIÇÃO · ARSENAL'} · ${c.rarity.toUpperCase()}</small><h3>${esc(c.name)}</h3><p>${gear?'A peça foi gravada e já está disponível para preparar em um deck.':'A carta foi inscrita na sua coleção e já pode entrar em seus decks.'}</p><div class="craft-result-reward"><span>QUANTIDADE<b>× ${craftedReveal.amount||1}</b></span>${gear?`<span>DURABILIDADE<b>${item?.durability??3}/${item?.maxDurability??3}</b></span><span>TIPO<b>EQUIPAMENTO PERSISTENTE</b></span>`:`<span>RARIDADE<b>${c.rarity.toUpperCase()}</b></span>`}<span>CUSTO<b>${gear?`◈ ${craftedReveal.cost?.coins??'—'} · ⚒ ${craftedReveal.cost?.scrap??'—'}`:`✧ ${craftedReveal.cost} FRAGMENTOS`}</b></span></div><div class="craft-result-actions"><button class="gold-button" data-modal="${gear?'market':'collection'}">${gear?'ABRIR RELICÁRIO':'VOLTAR AO ARSENAL'}</button><button class="menu-option" data-modal="decks">MONTAR DECK</button><button class="menu-option" data-close>CONTINUAR</button></div></div></section>`;}
  if(modal==='boosters'){title='O selo da primeira noite';body=`<div class="booster-stage pack-${packState}"><div class="pack-pedestal"><div class="pack-aura"></div><img class="official-pack" src="/assets/pack/vespera-cutout.png" alt="Booster oficial Bloodmoon, Crônicas de Véspera, Edição I, cinco cartas"><span class="pack-rune">✧</span></div><div class="pack-story"><small>CRÔNICAS DE VÉSPERA · EDIÇÃO I</small><h3>O próximo juramento<br>está em suas mãos.</h3><p>Cinco cartas. Uma nova relíquia.<br>Rompa o selo e descubra o que a noite guardou.</p><div class="pack-contents"><span><b>2</b> COMUNS</span><span><b>1</b> INCOMUM</span><span><b>1</b> RARA+</span><span><b>1</b> ITEM</span></div><button class="hunt-button" data-buy-booster ${busy||profile.coins<ECONOMY.boosterCost?'disabled':''}><small>◈ ${ECONOMY.boosterCost} MARCAS · SALDO ${profile.coins}</small><span>${packState==='opening'?'ROMPENDO O SELO…':'ABRIR BOOSTER'}</span></button><details class="pack-odds"><summary>Conteúdo e probabilidades</summary><p>Premium: 78% rara, 19% épica, 3% lendária. Equipamento: 60% comum, 25% incomum, 12% raro, 3% épico. Cada equipamento é uma peça persistente com 3 de durabilidade. Duplicatas de cartas acima do limite viram fragmentos.</p></details></div></div><div class="booster-results-slot">${boosterResultsHTML()}</div>`;}
  if(modal==='decks'){title='Câmara de guerra';body=deckModalBody();}
  if(modal==='market'){title='Mercado do Crepúsculo';body=marketModalBody();}
  if(modal==='contracts'){title='Contratos da caçada';body=`<p>Contratos são objetivos recorrentes. As recompensas entram automaticamente ao cumprir cada marco.</p><div class="contract-list contract-board">${CONTRACTS.map(c=>{const n=profile?.contracts?.[c.id]||0,pct=Math.min(100,n/c.goal*100);return `<article class="contract-bounty ${c.id}"><div class="contract-bounty-art"><img src="/assets/world/${c.id==='kills'?'forest-board':c.id==='wins'?'siege-board':'court-board'}.png" alt=""><span>${c.id==='kills'?'⚔':c.id==='wins'?'♛':'✧'}</span></div><div><strong>${c.name}</strong><small>${c.label}</small></div><b>${n}/${c.goal}</b><span class="contract-track"><i style="width:${pct}%"></i></span><em>+${c.reward.coins||0} Marcas ${c.reward.dust?`· +${c.reward.dust} Fragmentos`:''} ${c.reward.gear?'· ⚒ RELÍQUIA COMUM':''}</em><button class="gold-button" data-start="practice">PARTIR PARA A CAÇADA ↗</button></article>`;}).join('')}</div><p class="economy-footnote">Uma vitória também concede XP; ao subir de nível, você recebe Marcas e Fragmentos. Derrotas pagam uma recompensa menor para manter a progressão sem premiar desistências.</p>`;}
  if(modal==='legacy'){title='Seu legado';body=`<div class="legacy-profile"><b>${profile?.level||1}</b><div><h3>${esc(profile?.name||'Caçador')}</h3><p>${profile?.xp||0} XP · ${profile?.matches||0} caçadas · ${profile?.wins||0} vitórias</p></div></div>${levelProgressHTML(profile)}<div class="trophy ${(profile?.trophies||[]).includes('crown-of-the-buried')?'unlocked':''}">${art('boss')}<div><h3>Coroa do Rei Sepultado</h3><p>${(profile?.trophies||[]).includes('crown-of-the-buried')?'CONQUISTADA · Mordrath foi derrotado.':'Derrote o chefe da dungeon para conquistar.'}</p></div></div><p>Níveis e troféus registram sua jornada. Seus equipamentos persistem entre partidas e podem ser reparados no Relicário. A evolução dos aliados acontece dentro de cada combate.</p>`;}
  if(modal==='account'){title='Seu juramento';body=`<div class="account-summary"><img src="/assets/avatars/${profile.character?.avatar||((profile.selectedFaction||profile.starterFaction)==='werewolf'?'kael':'vesper')}.png" alt="Seu retrato"><h3>${esc(profile.name)}</h3><p>NÍVEL ${profile.level} · ${profile.accountId?'CONTA VINCULADA · PROGRESSO SALVO':'PROGRESSO DESTE NAVEGADOR'}</p>${profile.accountId?'':'<button class="gold-button" data-link-account>VINCULAR À MINHA CONTA</button>'}<button class="menu-option" data-modal="character">PERSONAGEM · RETRATO E ORIGEM</button><button class="menu-option" data-modal="loadout">PREPARAR EQUIPAMENTOS</button><button class="menu-option" data-logout>SAIR DA CONTA</button></div>`;}
  if(modal==='duel'){
    title=matchSearch?'Chamado enviado · encontre seu rival':'Buscar adversário';
    body=matchSearch?      `<div class="matchmaking-panel"><small>PAREAMENTO AUTOMÁTICO · ARENA DE VÉSPERA</small><div class="match-orbit" aria-hidden="true"><i></i><i></i><b>⚔</b></div><h3>A noite procura um igual.</h3><p>Você continuará nesta tela enquanto buscamos alguém próximo ao seu nível. A faixa de pareamento aumenta com o tempo de espera.</p><div class="match-details"><span>SUA LINHAGEM<b>${faction==='vampire'?'CORTE RUBRA':'ALCATEIA'}</b></span><span>SEU NÍVEL<b>${profile?.level||1} · RATING ${profile?.rating||1000}</b></span><span>NA FILA<b>${matchSearch.queued||1}</b></span></div><p class="match-time" aria-live="polite">BUSCANDO RIVAL…</p><button class="menu-option" data-match-cancel>CANCELAR BUSCA</button><button class="gold-button" data-match-solo>IR PARA A CAMPANHA SOLO</button></div>`:
      `<div class="matchmaking-panel"><small>PAREAMENTO AUTOMÁTICO · ARENA DE VÉSPERA</small><div class="match-orbit" aria-hidden="true"><i></i><i></i><b>⚔</b></div><h3>Um rival digno espera.</h3><p>Entre na fila 1 × 1 e o jogo encontrará alguém próximo à sua classificação. Sem códigos de sala.</p><div class="match-details"><span>DECK<b>${faction==='vampire'?'CORTE RUBRA':'ALCATEIA DO ECLIPSE'}</b></span><span>SEU NÍVEL<b>${profile?.level||1} · RATING ${profile?.rating||1000}</b></span><span>RECOMPENSA<b>XP · MARCAS · RATING</b></span></div><button class="hunt-button" data-match-start ${busy?'disabled':''}><span>BUSCAR ADVERSÁRIO</span><b>⚔</b></button><button class="menu-option" data-match-solo>JOGAR CAMPANHA SOLO</button></div>`;
  }
  if(modal==='chronicle'){title='Ecos do combate';body=`<ol class="chronicle">${[...room.log].reverse().map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;}
  if(modal==='pause'){title='A noite ainda não acabou';body=`<button class="hunt-button" data-close><span>VOLTAR À BATALHA</span></button><button class="menu-option" data-modal="guide">COMO JOGAR</button><button class="menu-option" data-home>REFÚGIO · MANTER PARTIDA</button><p>A partida continua disponível em “Retomar última partida”.</p>${room?.encounter?'<button class="menu-option" data-return-realms>VOLTAR AO MAPA · MANTER AVENTURA</button>':''}<button class="menu-option" data-concede>ABANDONAR · SEM RECOMPENSAS, COM DESGASTE</button>`;}
  if(modal.startsWith('art:')){const id=modal.slice(4),c=CARDS[id];title=c.name;body=`<div class="full-art-gallery">${CARD_ART[id]?`<img src="${CARD_ART[id]}" alt="${esc(c.name)}">`:art(id)}<p>${CARD_ART[id]?'Ilustração original · exibida na resolução disponível':'Arte provisória · ilustração exclusiva prevista no próximo lote'}</p></div>`;}
  if(modal.startsWith('card:')){const c=CARDS[modal.slice(5)],stats=c.type==='unit'?`<div class="inspect-stats"><span>⚔ ${c.attack} ATAQUE</span><span>♥ ${c.health} VIDA</span><span>♜ ${c.influence} INFLUÊNCIA</span></div>`:c.type==='equipment'?`<div class="inspect-stats"><span>⚔ +${c.attack} ATAQUE</span><span>♥ +${c.health} VIDA</span><span>⚒ PEÇA PERSISTENTE · ${ECONOMY.gearDurability} USOS</span></div><p>Em aliados, soma os atributos à criatura. Em seu líder, o ataque fortalece habilidades e a vida aumenta sua vida máxima.</p>`:`<div class="inspect-stats"><span>◈ ${c.cost} RECURSOS</span><span>${icon[c.type]}</span></div>`;title=c.name;body=`<div class="inspect-card full-card-inspect">${card(c.id)}<div class="inspect-copy"><small class="rarity-label ${c.rarity}">${c.rarity.toUpperCase()} · ${icon[c.type]} · CUSTO ${c.cost}</small><h3>${c.name}</h3>${stats}<p>${c.text}</p>${c.synergy?'<p class="inspect-synergy">✧ Sinergia na mesma frente · uma ativação por rodada. Bônus temporários expiram após o confronto.</p>':''}<blockquote>${c.flavor}</blockquote><button class="gold-button" data-full-art="${c.id}">AMPLIAR ILUSTRAÇÃO ↗</button><p class="art-status">${CARD_ART[c.id]?'ARTE ORIGINAL':'ARTE PROVISÓRIA · ILUSTRAÇÃO EXCLUSIVA PENDENTE'}</p><small>${FACTIONS[c.faction]?.name||'Relicário · Crônicas de Véspera'}</small></div></div>`;}
  return `<div class="modal-backdrop ${!room?'menu-backdrop':''} menu-${modal.split(':')[0]}"><section class="game-modal ${['collection','decks','boosters','market','contracts','craft-result'].includes(modal)||modal.startsWith('card:')?'wide':''} ${modal==='decks'?'deck-modal':''} ${modal.startsWith('card:')?'card-inspection-modal':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button data-close class="modal-close" aria-label="Fechar">✕</button><div class="window-heading"><p class="overline">BLOODMOON · SANGUE & FÚRIA</p><h2>${title}</h2><span class="window-ornament">◆</span></div>${!room?`<nav class="window-navigation">${[['collection','ARSENAL'],['decks','DECKS'],['boosters','BOOSTERS'],['market','RELICÁRIO'],['contracts','CONTRATOS']].map(([id,label])=>`<button data-modal="${id}" class="${modal===id?'active':''}">${label}</button>`).join('')}</nav>`:''}${body}</section></div>`;
}
function bindInspectionTilt(){const face=app.querySelector('.full-card-inspect > .game-card');if(!face)return;let activePointer=null,startX=0,startY=0,lastY=0,basis=null,gesture='pending',dragged=false,skipClick=false,clearSkipTimer=0,queued=null,frame=0;const reset=()=>{face.classList.remove('is-tilting');face.style.removeProperty('--inspect-tilt-x');face.style.removeProperty('--inspect-tilt-y');face.style.removeProperty('--inspect-shine-x');face.style.removeProperty('--inspect-shine-y');};const aim=(x,y,rect)=>{if(!rect?.width||!rect?.height)return;const nx=Math.max(0,Math.min(1,(x-rect.left)/rect.width)),ny=Math.max(0,Math.min(1,(y-rect.top)/rect.height));face.style.setProperty('--inspect-tilt-x',`${((.5-ny)*28).toFixed(2)}deg`);face.style.setProperty('--inspect-tilt-y',`${((nx-.5)*28).toFixed(2)}deg`);face.style.setProperty('--inspect-shine-x',`${(nx*100).toFixed(1)}%`);face.style.setProperty('--inspect-shine-y',`${(ny*100).toFixed(1)}%`);face.classList.add('is-tilting');};const schedule=(x,y,rect)=>{queued={x,y,rect};if(frame)return;frame=requestAnimationFrame(()=>{frame=0;if(queued)aim(queued.x,queued.y,queued.rect);});};face.addEventListener('pointerdown',event=>{if(event.button!==undefined&&event.button!==0)return;activePointer=event.pointerId;startX=event.clientX;startY=lastY=event.clientY;basis=face.getBoundingClientRect();gesture='pending';dragged=false;if(event.pointerType==='touch'){event.preventDefault();try{face.setPointerCapture(event.pointerId);}catch{}}});face.addEventListener('pointermove',event=>{if(event.pointerType==='touch'){if(activePointer!==event.pointerId)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.hypot(dx,dy)>5)dragged=true;if(gesture==='pending'&&Math.hypot(dx,dy)>8)gesture=Math.abs(dy)>Math.abs(dx)*1.25?'scroll':'tilt';if(gesture==='scroll'){const panel=face.closest('.game-modal');if(panel)panel.scrollTop+=lastY-event.clientY;lastY=event.clientY;return;}schedule(event.clientX,event.clientY,basis);return;}if(activePointer===null)schedule(event.clientX,event.clientY,face.getBoundingClientRect());else if(activePointer===event.pointerId){if(Math.hypot(event.clientX-startX,event.clientY-startY)>5)dragged=true;schedule(event.clientX,event.clientY,basis);}});face.addEventListener('pointerup',event=>{if(activePointer!==event.pointerId)return;activePointer=null;basis=null;reset();if(dragged){skipClick=true;clearTimeout(clearSkipTimer);clearSkipTimer=setTimeout(()=>skipClick=false,350);}});face.addEventListener('pointercancel',()=>{activePointer=null;basis=null;dragged=false;reset();});face.addEventListener('pointerleave',event=>{if(event.pointerType!=='touch'&&activePointer===null)reset();});face.addEventListener('click',event=>{if(!skipClick)return;event.preventDefault();event.stopImmediatePropagation();skipClick=false;clearTimeout(clearSkipTimer);});}
let previewAnchor=null,previewPointerX=-1,previewPointerY=-1,previewHideTimer,lastTouchPreviewAt=-2000,previewPointerDown=false;
document.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){previewPointerX=e.clientX;previewPointerY=e.clientY;}},{passive:true});
function schedulePreviewHide(){
 clearTimeout(previewHideTimer);
 previewHideTimer=setTimeout(()=>{
  const p=document.querySelector('#card-preview');
  if(p?.matches(':hover')||previewAnchor?.isConnected&&previewAnchor.matches(':hover,:focus-visible'))return;
  p?.classList.remove('visible');p?.setAttribute('aria-hidden','true');previewAnchor=null;
 },550);
}
function refreshCardPreviewAnchor(){
 const p=document.querySelector('#card-preview');if(!p?.classList.contains('visible'))return;
 if(previewPointerDown||!profile||modal?.startsWith('card:')||modal?.startsWith('art:')){p.classList.remove('visible');return;}
 const under=document.elementFromPoint(previewPointerX,previewPointerY);
 if(p.contains(under)){clearTimeout(previewHideTimer);return;}
 const anchor=under?.closest('[data-preview]');
 if(anchor&&anchor.dataset.preview===previewAnchor?.dataset.preview){previewAnchor=anchor;clearTimeout(previewHideTimer);return;}
 schedulePreviewHide();
}
document.addEventListener('pointerdown',e=>{previewPointerDown=true;document.querySelector('#card-preview')?.classList.remove('visible');hideMobileCardPeek();document.dispatchEvent(new Event('bloodmoon-dismiss-peeks'));},true);
document.addEventListener('pointerup',e=>{previewPointerDown=false;if(e.pointerType==='touch'){hideMobileCardPeek();if(worldOpen)realmTouchUntil=performance.now()+450;}},true);
document.addEventListener('pointercancel',()=>{previewPointerDown=false;hideMobileCardPeek();},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideMobileCardPeek();document.querySelector('#card-preview')?.classList.remove('visible');}},true);
app.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-preview]');if(e.pointerType!=='touch'||!room||modal||!el)return;const c=CARDS[el.dataset.preview],readOnly=!canAct()||c&&cardCost(room.players[room.seat],c)>room.players[room.seat].energy;if(readOnly||!el.hasAttribute('data-card')&&!selected)showMobileCardPeek(el.dataset.preview);});
document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){lastTouchPreviewAt=performance.now();document.querySelector('#card-preview')?.classList.remove('visible');if(!e.target.closest('.hand-fan'))hideMobileCardPeek();}},true);
function mountCardPreview(){if(!document.querySelector('#card-preview')){const preview=document.createElement('div');preview.id='card-preview';preview.className='card-preview';preview.setAttribute('aria-hidden','true');preview.addEventListener('mouseenter',()=>clearTimeout(previewHideTimer));preview.addEventListener('mouseleave',schedulePreviewHide);document.body.append(preview);}}
function bindHover(root=app){const preview=document.querySelector('#card-preview');if(!preview)return;root.querySelectorAll('[data-preview]').forEach(el=>{if(el.dataset.hoverBound)return;el.dataset.hoverBound='1';const show=e=>{if(e?.pointerType&&e.pointerType!=='mouse'||performance.now()-lastTouchPreviewAt<1200||matchMedia('(hover: none)').matches||previewPointerDown||pointerDrag?.started||e?.type==='focus'&&!el.matches(':focus-visible'))return;clearTimeout(previewHideTimer);previewAnchor=el;hideMobileCardPeek();if(modal?.startsWith('card:')||modal?.startsWith('art:'))return;const c=CARDS[el.dataset.preview];if(!c)return;const box=el.getBoundingClientRect(),right=box.left<innerWidth/2;preview.innerHTML=`<div class="preview-card-face">${card(c.id).replace('loading="lazy"','loading="eager"')}</div><div class="preview-card-copy"><small class="rarity-label ${c.rarity}">${c.rarity.toUpperCase()} · ${icon[c.type]} · CUSTO ${c.cost}</small><strong>${esc(c.name)}</strong><p>${esc(c.text)}</p>${c.type==='unit'?`<span>⚔ ${c.attack} · ♥ ${c.health} · ♜ ${c.influence}</span>`:c.type==='equipment'?`<span>⚔ +${c.attack} · ♥ +${c.health} · ⚒ ${effectNames[c.gearEffect]||'RELÍQUIA'}</span>`:''}</div>`;preview.style.left=right?'auto':'12px';preview.style.right=right?'12px':'auto';preview.style.top='50%';preview.classList.add('visible');preview.setAttribute('aria-hidden','false');};const hide=schedulePreviewHide;el.addEventListener('card-read',show);el.addEventListener('pointerenter',show);el.addEventListener('focus',show);el.addEventListener('mouseleave',hide);el.addEventListener('blur',hide);});}
async function guarded(work){if(busy)return;busy=true;const keepMarket=modal==='market';if(keepMarket)app.querySelector('.game-modal')?.setAttribute('aria-busy','true');else render();try{await work();}catch(e){toast(e.message);}finally{try{if(profile&&!room&&!worldOpen)await refreshReadiness();}finally{busy=false;render();}}}
async function presentCombat(next,old,frame){
  const before=structuredClone(room),events=next.events.filter(e=>e.id>old);
  await playCombatSequence({before,after:next,events,frame,speed:combatSpeed,cardHTML:id=>card(id),render:(state,event)=>{room=state;combatCaption=event?((event.seat===before.seat?'VOCÊ':'RIVAL')+' · '+(event.label||({damage:'IMPACTO',heal:event.drain?'DRENAGEM DE SANGUE':'RESTAURAÇÃO',play:'CARTA EM JOGO',death:'CRIATURA DERROTADA'}[event.type]||'RESOLVENDO'))):'';if(state.phase!=='finished')render();}});
  room=next;combatCaption='';
}
async function act(action){if(!canAct())return;if(room.tutorial&&action.type==='concede'){room=null;modal='academy';selected=null;render();return;}const id=room.roomId,old=room.events.at(-1)?.id||0,frame=captureCombatFrame(action);selected=null;await guarded(async()=>{try{const next=room.tutorial?academyAct(action):await api('/rooms/'+id+'/actions','POST',{version:room.version,action});await presentCombat(next,old,frame);if(next.phase==='finished'&&!next.tutorial)profile=await api('/profile');}catch(e){frame.cardFlight?.remove();frame.sourceFlight?.remove();combatCaption='';room=id==='academy'?academyView():await api('/rooms/'+id);throw e;}});}

async function start(mode){const riskMode=mode==='duel'&&document.querySelector('#duel-risk')?.checked?'blood-oath':'covenant';duelRisk=riskMode;await guarded(async()=>{await ensureProfile();readiness=await api(`/readiness?faction=${faction}`);if(readiness.activeRoom){room=await api(`/rooms/${readiness.activeRoom.id}`);selected=null;modal=null;remember();return;}if(!readiness.canStart){modal='readiness';return;}room=await api('/rooms','POST',{faction,mode,riskMode,deckId:profile.activeDecks?.[faction]});modal=null;selected=null;remember();playSound('start');});}
async function createDeckDraft(f){editingDeckId='new';editingDeckFaction=f;deckDraft=[];deckDraftName=f==='vampire'?'Novo juramento rubro':'Novo pacto da alcateia';render();}
async function saveDeckDraft(){const name=document.querySelector('#deck-name')?.value||deckDraftName,saved=profile.decks.find(deck=>deck.id===editingDeckId),owned=deckCollection(profile.collection||{},saved?.autoRefills||[]);try{validateDeck(deckDraft||[],editingDeckFaction,owned,profile.items||[]);}catch(e){toast(e.message);return;}await guarded(async()=>{const create=editingDeckId==='new',result=await api(create?'/decks':`/decks/${editingDeckId}`,create?'POST':'PUT',{name,cards:deckDraft});profile=result.profile;if(create)editingDeckId=result.deck.id;deckDraftName=name;deckDraft=[...result.deck.cards];toast('Deck salvo. Itens usados serão reservados e podem se desgastar na partida.');});}
async function activateDeck(id){await guarded(async()=>{const result=await api(`/decks/${id}/activate`,'POST',{});profile=result.profile;faction=profile.selectedFaction;localStorage.setItem('bloodmoon.faction',faction);await refreshReadiness();});}
function selectCard(uid){if(!canAct())return;const instance=room.players[room.seat].hand.find(c=>c.uid===uid);if(!instance)return;if(cardCost(room.players[room.seat],CARDS[instance.cardId])>room.players[room.seat].energy){toast('Recursos insuficientes.');return;}selected=selected?.uid===uid?null:{kind:'card',uid,cardId:instance.cardId};playSound('select');render();}
async function refreshMarket(){const [result,purchases]=await Promise.all([api('/market'),api('/market/orders').catch(error=>{if(error.message==='Rota não encontrada.')return {orders:[]};throw error;})]);profile=result.profile;marketItems=result.inventory||[];marketOffers=result.offers||[];setPurchaseOrders(purchases.orders);}
function marketModalBody(){return tradingHall(profile,marketItems,marketOffers,card);}
async function deploy(lane){if(selected?.kind!=='card'||!canAct())return;const c=CARDS[selected.cardId];if(c.type==='equipment'||['pounce','rally','guard'].includes(c.effect)){toast('Escolha um aliado ou equipe seu líder.');return;}if(['damage','execute','rend','drain'].includes(c.effect)){toast('Clique no inimigo que receberá o ataque.');return;}await act({type:'play',uid:selected.uid,lane});}
function canDropCard(cardId,laneEl,unitEl,heroEl=null){
  const c=CARDS[cardId];if(!c)return false;
  if(heroEl)return c.type==='equipment'&&Number(heroEl.dataset.seat)===room.seat&&(room.players[room.seat].heroGear||[]).length<1;
  if(!laneEl)return false;
  if(!unitEl)return !['damage','execute','rend','drain'].includes(c.effect)&&c.type!=='equipment'&&!['pounce','rally','guard'].includes(c.effect);
  const friendly=Number(unitEl.dataset.seat)===room.seat;
  if(c.type==='equipment'||['pounce','rally','guard'].includes(c.effect))return friendly&&unitEl.dataset.laneId===laneEl.dataset.zone;
  if(['damage','execute','rend','drain'].includes(c.effect))return !friendly&&unitEl.dataset.laneId===laneEl.dataset.zone;
  if(c.type==='spell')return true;
  return c.type==='unit'&&friendly&&unitEl.dataset.laneId===laneEl.dataset.zone;
}
function clearDragState(){
  document.querySelectorAll('.drop-hover,.drop-invalid,.drop-target,.drop-target-invalid,.dragging-card').forEach(el=>el.classList.remove('drop-hover','drop-invalid','drop-target','drop-target-invalid','dragging-card'));
  document.querySelector('.arena')?.classList.remove('dragging');
}
function updateDragTarget(x,y){
  document.querySelectorAll('.drop-hover,.drop-invalid,.drop-target,.drop-target-invalid').forEach(el=>el.classList.remove('drop-hover','drop-invalid','drop-target','drop-target-invalid'));
  const target=document.elementFromPoint(x,y),lane=target?.closest('.battle-lane'),unit=target?.closest('.fighter'),heroTarget=target?.closest('.hero-portrait');
  if(heroTarget){const valid=canDropCard(pointerDrag.cardId,null,null,heroTarget);heroTarget.classList.add(valid?'drop-target':'drop-target-invalid');}
  else if(lane){const valid=canDropCard(pointerDrag.cardId,lane,unit);lane.classList.add(valid?'drop-hover':'drop-invalid');if(unit)unit.classList.add(valid?'drop-target':'drop-target-invalid');}
  return {target,lane,unit,heroTarget};
}
let mobilePeekTimer;
installBattleKeyboard(()=>({playing:room?.phase==='playing',modal:!!modal,dragging:!!pointerDrag,canAct:canAct()}));
installPlayerJourney(()=>({profile,room,modal,busy,worldOpen,realmTab,accountOpen,hasStarted,introPlaying}),async(id,step)=>{const owner=profile?.id;const result=await api('/journey/lesson','POST',{id,step});if(profile?.id===owner)profile.journey=result.journey;});
function positionMobileCardPeek(){
  const panel=document.querySelector('#touch-card-preview'),hand=document.querySelector('.hand-dock');
  if(!panel||!hand)return;
  const top=hand.getBoundingClientRect().top;
  panel.style.setProperty('--peek-bottom',`${Math.max(12,innerHeight-top+12)}px`);
  panel.style.setProperty('--peek-space',`${Math.max(80,top-28)}px`);
}
window.addEventListener('resize',positionMobileCardPeek,{passive:true});
function showMobileCardPeek(id){
  if(innerWidth>1024||modal)return;
  document.querySelector('#card-preview')?.classList.remove('visible');
  const c=CARDS[id];if(!c)return;
  let panel=document.querySelector('#touch-card-preview');
  if(!panel){panel=document.createElement('aside');panel.id='touch-card-preview';panel.className='touch-card-preview';panel.setAttribute('aria-hidden','true');document.body.append(panel);}
  panel.innerHTML=`<div class="touch-preview-face">${card(id).replace('loading="lazy"','loading="eager"')}</div><div class="touch-preview-copy"><small>${rarityNames[c.rarity]} · ${icon[c.type]} · CUSTO ${c.cost}</small><strong>${esc(c.name)}</strong><p>${esc(c.text)}</p><span>${c.type==='unit'?`⚔ ${c.attack} · ♥ ${c.health} · ♜ ${c.influence}`:c.type==='equipment'?`⚔ +${c.attack} · ♥ +${c.health} · ⚒ ${effectNames[c.gearEffect]||'RELÍQUIA'}`:esc(c.flavor)}</span></div>`;
  positionMobileCardPeek();panel.classList.add('visible');clearTimeout(mobilePeekTimer);
}
function hideMobileCardPeek(delay=0){clearTimeout(mobilePeekTimer);const panel=document.querySelector('#touch-card-preview');if(!panel)return;if(delay)mobilePeekTimer=setTimeout(()=>panel.classList.remove('visible'),delay);else panel.classList.remove('visible');}
function focusTouchedCard(el,scrubbed=true){
  const instance=room.players[room.seat].hand.find(c=>c.uid===el.dataset.card);if(!instance)return false;
  if(cardCost(room.players[room.seat],CARDS[instance.cardId])>room.players[room.seat].energy){if(pointerDrag.previewedUid!==instance.uid){pointerDrag.previewedUid=instance.uid;document.querySelectorAll('.hand-fan [data-card]').forEach(card=>card.classList.remove('touch-scrub-focus','selected'));showMobileCardPeek(instance.cardId);}return false;}
  pointerDrag.previewedUid=null;
  pointerDrag.uid=instance.uid;pointerDrag.cardId=instance.cardId;pointerDrag.source=el;if(scrubbed)pointerDrag.scrubbed=true;
  selected={kind:'card',uid:instance.uid,cardId:instance.cardId};
  document.querySelectorAll('.hand-fan [data-card]').forEach(card=>{const cur=card===el;card.classList.toggle('touch-scrub-focus',cur);card.classList.toggle('selected',cur);if(!cur)try{card.blur();}catch{}});
  showMobileCardPeek(instance.cardId);playSound('select');return true;
}
const isTextInput=el=>el&&(el.tagName==='INPUT'||el.tagName==='TEXTAREA'||el.isContentEditable);
window.addEventListener('selectstart',e=>{if(!isTextInput(e.target))e.preventDefault();},{capture:true});
window.addEventListener('dragstart',e=>{if(!isTextInput(e.target))e.preventDefault();},{capture:true});
window.addEventListener('contextmenu',e=>{if(!isTextInput(e.target))e.preventDefault();},{capture:true});
app.addEventListener('pointerdown',e=>{
  const el=e.target.closest('[data-card]');if(!el||!canAct()||e.button!==0)return;
  const instance=room.players[room.seat].hand.find(c=>c.uid===el.dataset.card);if(!instance||cardCost(room.players[room.seat],CARDS[instance.cardId])>room.players[room.seat].energy)return;
  const touch=e.pointerType==='touch';
  pointerDrag={uid:instance.uid,originUid:instance.uid,previousSelection:selected?.uid||null,cardId:instance.cardId,source:el,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,pointerId:e.pointerId,started:false,ghost:null,mode:touch?'scrub':'drag',scrubbed:false};
  if(touch)focusTouchedCard(el,false);
  try{el.setPointerCapture(e.pointerId);}catch{}
});
document.addEventListener('pointermove',e=>{
  if(!pointerDrag||pointerDrag.pointerId!==e.pointerId)return;
  pointerDrag.x=e.clientX;pointerDrag.y=e.clientY;
  if(pointerDrag.mode==='scrub'){
    const target=document.elementFromPoint(e.clientX,e.clientY),touched=target?.closest('.hand-fan [data-card]');
    if(touched&&touched.dataset.card!==pointerDrag.uid)focusTouchedCard(touched);
    const lane=target?.closest('.battle-lane'),lifted=e.clientY<pointerDrag.startY-28;
    if(!lane&&!lifted)return;
    pointerDrag.mode='drag';hideMobileCardPeek();
  }
  if(!pointerDrag.started&&Math.hypot(e.clientX-pointerDrag.startX,e.clientY-pointerDrag.startY)>9){
    pointerDrag.started=true;pointerDrag.source.classList.add('dragging-card');document.querySelector('.arena')?.classList.add('dragging');
    pointerDrag.ghost=pointerDrag.source.cloneNode(true);pointerDrag.ghost.removeAttribute('data-card');pointerDrag.ghost.removeAttribute('data-preview');pointerDrag.ghost.classList.remove('selected','affordable','unaffordable');pointerDrag.ghost.classList.add('pointer-card-ghost');pointerDrag.ghost.setAttribute('aria-hidden','true');pointerDrag.ghost.style.width=`${pointerDrag.source.getBoundingClientRect().width}px`;pointerDrag.ghost.style.height=`${pointerDrag.source.getBoundingClientRect().height}px`;document.body.append(pointerDrag.ghost);
  }
  if(!pointerDrag.started)return;
  if(pointerDrag.ghost){pointerDrag.ghost.style.left=`${e.clientX-pointerDrag.ghost.offsetWidth/2}px`;pointerDrag.ghost.style.top=`${e.clientY-pointerDrag.ghost.offsetHeight/2}px`;}
  updateDragTarget(e.clientX,e.clientY);
});
document.addEventListener('pointerup',async e=>{
  if(!pointerDrag||pointerDrag.pointerId!==e.pointerId)return;
  const drag=pointerDrag;pointerDrag=null;drag.ghost?.remove();clearDragState();
  if(drag.mode==='scrub'){
    hideMobileCardPeek();e.preventDefault();suppressedCardClick={uid:drag.uid,originUid:drag.originUid,until:performance.now()+500};
    if(!drag.scrubbed&&drag.previousSelection===drag.uid)selected=null;
    document.querySelectorAll('.touch-scrub-focus').forEach(card=>card.classList.remove('touch-scrub-focus'));render();
    return;
  }
  hideMobileCardPeek();
  if(!drag.started)return;
  e.preventDefault();suppressedCardClick={uid:drag.originUid||drag.uid,until:performance.now()+500};
  selected={kind:'card',uid:drag.uid,cardId:drag.cardId};
  const target=document.elementFromPoint(e.clientX,e.clientY),lane=target?.closest('.battle-lane'),unit=target?.closest('.fighter'),heroTarget=target?.closest('.hero-portrait');
  if(heroTarget){if(!canDropCard(drag.cardId,null,null,heroTarget)){render();toast('Seu líder só pode usar um equipamento por partida.');return;}await act({type:'play',uid:drag.uid,lane:'court',target:'hero'});return;}
  if(!lane){render();toast('Solte a carta dentro de uma das três frentes.');return;}
  if(!canDropCard(drag.cardId,lane,unit)){render();toast('Esse alvo não aceita esta carta. A carta continua selecionada.');return;}
  const c=CARDS[drag.cardId];
  if(unit&&(c.type==='equipment'||['pounce','rally','guard','damage','execute','rend','drain'].includes(c.effect)))await act({type:'play',uid:drag.uid,lane:lane.dataset.zone,target:unit.dataset.unit});
  else await deploy(lane.dataset.zone);
});
document.addEventListener('pointercancel',e=>{
  if(!pointerDrag||pointerDrag.pointerId!==e.pointerId)return;
  const drag=pointerDrag;pointerDrag=null;drag.ghost?.remove();clearDragState();
  hideMobileCardPeek();document.querySelectorAll('.touch-scrub-focus').forEach(card=>card.classList.remove('touch-scrub-focus'));
  if(drag.started||drag.scrubbed){selected={kind:'card',uid:drag.uid,cardId:drag.cardId};render();if(drag.started)toast('Arrasto cancelado. A carta continua selecionada.');}
});
