app.addEventListener('submit',async e=>{if(e.target.id!=='account-form')return;e.preventDefault();if(authBusy)return;const form=e.target,values=new FormData(form);authBusy=true;authError='';const submit=form.querySelector('button');submit.disabled=true;try{const session=await api('/auth/'+authMode,'POST',{email:values.get('email'),password:values.get('password'),claimLegacy:values.get('claimLegacy')==='on'});profile=session.profile;faction=profile.selectedFaction||profile.starterFaction||'vampire';token=null;localStorage.removeItem('bloodmoon.profile');accountOpen=false;room=null;worldOpen=false;lastRoom=null;sessionStorage.removeItem('bloodmoon.room');onboardingStep=0;modal=profile.onboardingComplete===false?'onboarding':null;await refreshReadiness();playSound('start');}catch(error){authError=error.message;}finally{authBusy=false;render();}});

async function receiveMatch(result){if(result.state!=='matched')return false;matchSearch=null;room=await api('/rooms/'+result.roomId);profile=await api('/profile');worldOpen=false;selected=null;modal=null;remember();playSound('start');render();return true;}
async function searchMatch(){await guarded(async()=>{await ensureProfile();const result=await api('/matchmaking','POST',{faction});if(!await receiveMatch(result)){matchSearch=result;modal='duel';}});}
async function cancelMatch(){try{if(matchSearch){matchSearch=null;const result=await api('/matchmaking','DELETE');if(await receiveMatch(result))return false;}modal=null;render();return true;}catch(error){toast(error.message);return false;}}
setInterval(async()=>{if(!matchSearch||matchPolling||busy||document.hidden)return;const time=document.querySelector('.match-time');if(time)time.textContent='BUSCANDO HÁ '+Math.max(0,Math.floor((Date.now()-matchSearch.joinedAt)/1000))+'s';matchPolling=true;try{const result=await api('/matchmaking','POST',{faction});if(matchSearch)await receiveMatch(result);}catch(error){matchSearch=null;toast(error.message);render();}finally{matchPolling=false;}},2500);

