app.addEventListener('submit',async e=>{
 if(e.target.id!=='character-form')return;e.preventDefault();if(busy)return;
 const form=e.target,fields=new FormData(form),creation=form.dataset.onboarding==='true';
 const input={name:String(fields.get('name')||'').trim(),avatar:fields.get('avatar'),origin:fields.get('origin'),faction};
 await guarded(async()=>{const result=await api(creation?'/onboarding':'/character','POST',input);profile=result.profile;modal=null;await refreshReadiness();playSound('start');});
 if(!modal&&profile.character)await playMotionScene({title:profile.name,text:creation?'Seu juramento atravessa as ruínas. Domine a Corte, sustente seus aliados e conquiste seu lugar em Véspera.':'A noite se lembrará deste rosto.',portrait:profile.character.avatar});if(creation&&profile.character){modal='academy';render();}
});

let realmStream=null,realmPushPending=false,lastRealmPush=0,realmTouchUntil=0;
function applyRealmSnapshot(next){
 if(realmData?.liveWorld&&next.liveWorld&&worldOpen&&!room&&realmTab==='map'){
  const live=realmData.liveWorld;
  if(next.liveWorld.serverTime<live.serverTime||(next.liveWorld.player?.moveSeq||0)<(live.player?.moveSeq||0))next.liveWorld=live;
  realmData=next;profile={...profile,...next.profile};
  if(!modal)updateRealmWorld(app,realmData);
  return;
 }
 const changed=next.version!==realmData?.version||next.player.version!==realmData?.player.version||JSON.stringify(next.online.map(p=>[p.id,p.location,p.busy]))!==JSON.stringify(realmData?.online.map(p=>[p.id,p.location,p.busy]));
 if(!changed)return;
 if(!worldOpen||room||modal||worldTableInteracting()||menuPointerDown||performance.now()<realmTouchUntil){realmPushPending=true;return;}
 realmData=next;render();
}
setInterval(async()=>{
 const visible=worldOpen&&!room&&!document.hidden&&!!profile?.accountId;
 if(!visible){realmStream?.close();realmStream=null;realmPushPending=false;return;}
 if(!realmStream){
  realmStream=new EventSource('/api/realms/events');
  realmStream.addEventListener('world',()=>{realmPushPending=true;});
  realmStream.addEventListener('realm-live',event=>{try{applyLiveWorld(JSON.parse(event.data).liveWorld);}catch{}});
 }
 if(!realmPushPending||busy||modal||realmPolling||worldTableInteracting()||menuPointerDown||performance.now()<realmTouchUntil||Date.now()-lastRealmPush<1500)return;
 realmPushPending=false;realmPolling=true;lastRealmPush=Date.now();
 try{applyRealmSnapshot(await api('/realms'));}catch{}finally{realmPolling=false;}
},500);
let liveRealmPolling=false;
setInterval(async()=>{
 if(!worldOpen||room||document.hidden||realmTab!=='map'||!realmData?.liveWorld||liveRealmPolling||realmStream?.readyState===EventSource.OPEN)return;
 liveRealmPolling=true;
 try{const owner=realmData.player.publicId,next=await api('/realms/world');if(owner===realmData?.player?.publicId)applyLiveWorld(next.liveWorld);}catch{}finally{liveRealmPolling=false;}
},750);
